// Validate input parameters
if (ckh == nullptr || aTab == nullptr || aTab->tab == nullptr) {
    return;
}

// Cache important properties
const size_t hashpower = aTab->hashpower;
const size_t tab_size = static_cast<size_t>(1) << hashpower;
ckh_item_t** old_tab = aTab->tab;
ckh_item_t** new_tab = ckh->tab;

// Initialize new table slots to nullptr
for (size_t i = 0; i < (static_cast<size_t>(1) << ckh->hashpower); i++) {
    new_tab[i] = nullptr;
}

// Reinsert all elements from old table
for (size_t i = 0; i < tab_size; i++) {
    ckh_item_t* item = old_tab[i];
    while (item != nullptr) {
        ckh_item_t* next = item->next;
        size_t hv = ckh_hash(ckh, item->key, item->key_length);
        size_t idx = hv & ((static_cast<size_t>(1) << ckh->hashpower) - 1);

        // Insert at head of new table's chain
        item->next = new_tab[idx];
        new_tab[idx] = item;

        item = next;
    }
}

// Update metadata
ckh->count = aTab->count;
ckh->hashpower = aTab->hashpower;
ckh->n_items = aTab->n_items;
ckh->resize_threshold = aTab->resize_threshold;
ckh->low_water_mark = aTab->low_water_mark;
ckh->high_water_mark = aTab->high_water_mark;
ckh->generation = aTab->generation + 1;

